def islands(grid: list[str]) -> int:
    if not grid:
        return 0

    rows = len(grid)
    visited = set()
    count = 0

    for r in range(rows):
        for c in range(len(grid[r])):
            if grid[r][c] == '1' and (r, c) not in visited:
                count += 1
                stack = [(r, c)]
                visited.add((r, c))

                while stack:
                    x, y = stack.pop()

                    for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nx, ny = x + dx, y + dy

                        if 0 <= nx < rows and 0 <= ny < len(grid[nx]):
                            if grid[nx][ny] == '1' and (nx, ny) not in visited:
                                visited.add((nx, ny))
                                stack.append((nx, ny))

    return count
