def wrap(text: str, width: int) -> list[str]:
    words = text.split()
    if not words:
        return []

    if width <= 0:
        return words

    lines = []
    current = []

    for word in words:
        if len(word) > width:
            if current:
                lines.append(" ".join(current))
                current = []
            lines.append(word)
        else:
            if not current:
                current = [word]
            elif len(" ".join(current)) + 1 + len(word) <= width:
                current.append(word)
            else:
                lines.append(" ".join(current))
                current = [word]

    if current:
